import cv2,numpy as np
im=cv2.imread('first_frame.png'); g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
# line slope fitting on ball lower edge using x range and boundary max gradient
for direction in ['top','bottom','left','right']:
 pts=[]
 if direction in ['top','bottom']:
  for x in range(386,459):
   if direction=='top': ys=range(210,245)
   else: ys=range(270,304)
   # gradient y and dark/table threshold
   vals=[]
   for y in ys:
    vals.append(abs(float(g[y+1,x])-float(g[y-1,x])))
   i=int(np.argmax(vals));y=list(ys)[i]
   pts.append((x,y,vals[i]))
 else:
  for y in range(218,299):
   if direction=='left': xs=range(365,410)
   else:xs=range(435,480)
   vals=[]
   for x in xs:vals.append(abs(float(g[y,x+1])-float(g[y,x-1])))
   i=int(np.argmax(vals));x=list(xs)[i];pts.append((x,y,vals[i]))
 pts=np.array(pts)
 print(direction,'strong n',sum(pts[:,2]>15),'range',pts[:,2].min(),pts[:,2].max())
 # use points above 20, fit linear
 p=pts[pts[:,2]>20]
 if len(p)>2:
  if direction in ['top','bottom']:
   coef=np.polyfit(p[:,0],p[:,1],1)
  else: coef=np.polyfit(p[:,1],p[:,0],1)
  print('coef',coef,'n',len(p))
PY"
